# Web dashboard HTML for live_collect_server
from __future__ import annotations

DASHBOARD_HTML = '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>直播间数据</title>\n<style>\n*{box-sizing:border-box}body{font-family:system-ui,sans-serif;margin:0;background:#f4f6f8;color:#222}\n.hdr{background:#1a73e8;color:#fff;padding:16px 20px}.hdr h1{margin:0;font-size:20px}\n.wrap{max-width:1200px;margin:0 auto;padding:16px}\n.cards{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px}\n.card{background:#fff;border-radius:8px;padding:14px 18px;min-width:160px;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.card .n{font-size:28px;font-weight:700;color:#1a73e8}.card .l{font-size:13px;color:#666;margin-top:4px}\n.bar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;align-items:center}\ninput,button,select{padding:8px 12px;border:1px solid #ccc;border-radius:6px;font-size:14px}\nbutton{background:#1a73e8;color:#fff;border:none;cursor:pointer}button:disabled{opacity:.5}\ntable{width:100%;border-collapse:collapse;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 1px 3px rgba(0,0,0,.08)}\nth,td{padding:10px 12px;text-align:left;border-bottom:1px solid #eee;font-size:13px}\nth{background:#fafafa}tr:hover td{background:#f9fbff}\n.pager{display:flex;gap:8px;align-items:center;margin-top:12px}\n.muted{color:#888;font-size:13px}.err{color:#c62828;padding:12px;background:#ffebee;border-radius:6px}\na{color:#1a73e8}\n</style>\n</head>\n<body>\n<div class="hdr"><h1>抖音直播间采集数据</h1></div>\n<div class="wrap">\n<div class="cards">\n<div class="card"><div class="n" id="stUnique">-</div><div class="l">唯一直播间</div></div>\n<div class="card"><div class="n" id="stExtract">-</div><div class="l">累计提取次数</div></div>\n<div class="card"><div class="l">数据库</div><div class="l" id="stDb" style="font-size:12px;word-break:break-all">-</div></div>\n</div>\n<div class="bar">\n<input id="q" placeholder="搜索 live_id" style="flex:1;min-width:180px">\n<select id="limit"><option value="20">20条/页</option><option value="50" selected>50条/页</option><option value="100">100条/页</option></select>\n<button onclick="load(1)">查询</button>\n<button onclick="loadStats();load(page)">刷新</button>\n<span class="muted" id="status"></span>\n</div>\n<div id="err"></div>\n<table><thead><tr><th>#</th><th>live_id</th><th>房间人数</th><th>添加时间</th><th>修改时间</th><th>提取时间</th><th>提取次数</th></tr></thead>\n<tbody id="tb"></tbody></table>\n<div class="pager"><button id="btnPrev" onclick="load(page-1)">上一页</button><span class="muted" id="pgInfo">-</span><button id="btnNext" onclick="load(page+1)">下一页</button></div>\n</div>\n<script>\nlet page=1,total=0;\nfunction esc(s){s=(s===undefined||s===null)?"":String(s);return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}\nfunction val(v,d){return (v===undefined||v===null)?d:v;}\nasync function loadStats(){\n  try{\n    var r=await fetch("/api/stats");\n    if(!r.ok) throw new Error("stats http "+r.status);\n    var j=await r.json();\n    if(!j.ok) throw new Error(j.error||"stats failed");\n    document.getElementById("stUnique").textContent=val(j.unique_rooms,"-");\n    document.getElementById("stExtract").textContent=val(j.total_extractions,"-");\n    document.getElementById("stDb").textContent=j.db_path||"";\n  }catch(e){\n    document.getElementById("stDb").textContent=String(e.message||e);\n  }\n}\nfunction emptyRow(tb){\n  var tr=document.createElement("tr");\n  var td=document.createElement("td");\n  td.colSpan=7; td.className="muted"; td.style.textAlign="center";\n  td.textContent="\\u6682\\u65e0\\u6570\\u636e";\n  tr.appendChild(td); tb.appendChild(tr);\n}\nasync function load(p){\n  page=Math.max(1,p||1);\n  var q=document.getElementById("q").value.trim();\n  var limit=parseInt(document.getElementById("limit").value,10)||50;\n  document.getElementById("status").textContent="\\u52a0\\u8f7d\\u4e2d...";\n  document.getElementById("err").innerHTML="";\n  try{\n    var url="/api/rooms/list?page="+page+"&limit="+limit+(q?"&q="+encodeURIComponent(q):"");\n    var r=await fetch(url);\n    var j=await r.json();\n    if(!r.ok||!j.ok) throw new Error(j.detail||j.error||("http "+r.status));\n    total=j.total||0;\n    var tb=document.getElementById("tb");\n    tb.innerHTML="";\n    var rows=j.rooms||[];\n    if(!rows.length){ emptyRow(tb); }\n    rows.forEach(function(row,i){\n      var tr=document.createElement("tr");\n      var lid=esc(row.live_id||"");\n      tr.innerHTML="<td>"+((page-1)*limit+i+1)+"</td>"\n        +"<td><a href=\\"https://live.douyin.com/"+lid+"\\" target=\\"_blank\\" rel=\\"noopener\\">"+lid+"</a></td>"\n        +"<td>"+esc(val(row.user_count,""))+"</td>"\n        +"<td>"+esc(row.added_at||"")+"</td>"\n        +"<td>"+esc(row.modified_at||"")+"</td>"\n        +"<td>"+esc(row.extracted_at||"")+"</td>"\n        +"<td>"+esc(val(row.extract_count,""))+"</td>";\n      tb.appendChild(tr);\n    });\n    var pages=Math.max(1,Math.ceil(total/limit));\n    document.getElementById("pgInfo").textContent="\\u7b2c "+page+" / "+pages+" \\u9875\\uff0c\\u5171 "+total+" \\u6761";\n    document.getElementById("btnPrev").disabled=page<=1;\n    document.getElementById("btnNext").disabled=page>=pages;\n    document.getElementById("status").textContent="ok "+new Date().toLocaleTimeString();\n  }catch(e){\n    document.getElementById("err").innerHTML=\'<div class="err">\'+esc(e.message||e)+\'</div>\';\n    document.getElementById("status").textContent="";\n  }\n}\ndocument.getElementById("q").addEventListener("keydown",function(e){if(e.key==="Enter")load(1);});\nloadStats();load(1);setInterval(loadStats,15000);\n</script>\n</body></html>'
